# Move Agent Definitions to MAD Built-in

## Overview
Move hardcoded agent definitions (claude, opencode) from per-instance config.json into Python code as built-in defaults. Extend agent_for_phase to support per-phase model selection. Custom agents are explicitly out of scope.

## Step 1: Define BUILTIN_AGENTS in config.py

Add a module-level constant in `pipeline/config.py`:

```python
BUILTIN_AGENTS: Dict[str, dict] = {
    "claude": {
        "command": "claude",
        "headless_flag": "-p",
        "headless_extra_flags": ["--dangerously-skip-permissions"],
        "model_flag": "--model",
    },
    "opencode": {
        "command": "opencode",
        "headless_flag": "",
        "headless_extra_flags": ["run"],
        "model_flag": "-m",
    },
}
```

Note: `model_flag` is explicitly included in BUILTIN_AGENTS (not just as an AgentConfig default) to make the configuration self-documenting and avoid confusion about where the value comes from.

Add `model_flag` and `model` fields to `AgentConfig` dataclass:
```python
@dataclass
class AgentConfig:
    name: str
    command: str
    headless_flag: str
    headless_extra_flags: List[str]
    model_flag: str = "--model"
    model: Optional[str] = None
```

Add `PhaseConfig` dataclass:
```python
@dataclass
class PhaseConfig:
    """Configuration for a single phase's agent assignment."""
    agent: str
    model: Optional[str] = None
```

## Step 2: Update Config.agents property

Change `Config.agents` to source from `BUILTIN_AGENTS` instead of config.json:

```python
@property
def agents(self) -> Dict[str, AgentConfig]:
    result = {}
    for name, cfg in BUILTIN_AGENTS.items():
        result[name] = AgentConfig(
            name=name,
            command=cfg["command"],
            headless_flag=cfg["headless_flag"],
            headless_extra_flags=cfg.get("headless_extra_flags", []),
            model_flag=cfg.get("model_flag", "--model"),
        )
    return result
```

This completely removes the dependency on the `agents` key in config.json.

## Step 3: Rename current_agent to default_agent

Update `Config.current_agent_name` to read `default_agent` with backward-compatible fallback:

```python
@property
def current_agent_name(self) -> str:
    return self._data.get("default_agent", self._data.get("current_agent", "claude"))
```

Update `set_current_agent` to write `default_agent` and always remove old `current_agent` key:
```python
def set_current_agent(self, name: str) -> None:
    if name not in BUILTIN_AGENTS:
        raise ValueError(f"Unknown agent: {name}. Available: {list(BUILTIN_AGENTS.keys())}")
    self._data["default_agent"] = name
    self._data.pop("current_agent", None)
    self._save()
```

## Step 4: Extend agent_for_phase to support model selection

Change `agent_for_phase` config format to support both string (backward-compatible) and object format:

**New format:**
```json
"agent_for_phase": {
    "planning": { "agent": "claude", "model": "claude-sonnet-4-20250514" },
    "implementing": "opencode",
    "review": { "agent": "claude" }
}
```

**Behavior rules for model field:**
- Missing `model` key or `null` value: use agent's default model (no --model flag passed)
- Empty string `""`: treated same as missing (no model override)
- String value: passed via the agent's `model_flag`
- Invalid model names are NOT validated at config time (validation is the agent's responsibility at runtime)

**Update `agent_for_phase` property** to normalize both formats:
```python
@property
def agent_for_phase(self) -> Dict[str, PhaseConfig]:
    raw = self._data.get("agent_for_phase", {})
    result = {}
    for phase, value in raw.items():
        if isinstance(value, str):
            result[phase] = PhaseConfig(agent=value, model=None)
        elif isinstance(value, dict):
            result[phase] = PhaseConfig(
                agent=value.get("agent", self.current_agent_name),
                model=value.get("model") or None,  # empty string -> None
            )
        else:
            result[phase] = PhaseConfig(agent=self.current_agent_name, model=None)
    return result
```

**Update `get_agent_for_phase`** to return AgentConfig with model set:
```python
def get_agent_for_phase(self, phase: str) -> AgentConfig:
    phase_cfg = self.agent_for_phase.get(phase)
    if phase_cfg is None:
        return self.current_agent
    agent_name = phase_cfg.agent
    if agent_name == "default":
        agent_name = self.current_agent_name
    agents = self.agents
    if agent_name not in agents:
        return self.current_agent
    agent_config = agents[agent_name]
    if phase_cfg.model:
        # Create a copy with model set (don't mutate the cached config)
        agent_config = AgentConfig(
            name=agent_config.name,
            command=agent_config.command,
            headless_flag=agent_config.headless_flag,
            headless_extra_flags=agent_config.headless_extra_flags,
            model_flag=agent_config.model_flag,
            model=phase_cfg.model,
        )
    return agent_config
```

**Update `set_agent_for_phase`** to validate against BUILTIN_AGENTS and accept model:
```python
def set_agent_for_phase(self, phase: str, agent_name: str, model: Optional[str] = None) -> None:
    if "agent_for_phase" not in self._data:
        self._data["agent_for_phase"] = {}
    if agent_name != "default" and agent_name not in BUILTIN_AGENTS:
        raise ValueError(f"Unknown agent: {agent_name}. Available: {list(BUILTIN_AGENTS.keys())}")
    if model:
        self._data["agent_for_phase"][phase] = {"agent": agent_name, "model": model}
    else:
        self._data["agent_for_phase"][phase] = agent_name
    self._save()
```

**Update `set_agent_for_phases`** to accept both string and dict values:
```python
def set_agent_for_phases(self, phase_mapping: dict) -> None:
    """Set agent (and optional model) for multiple phases.
    Values can be strings (agent name only) or dicts with 'agent' and optional 'model' keys."""
    if "agent_for_phase" not in self._data:
        self._data["agent_for_phase"] = {}
    for phase, value in phase_mapping.items():
        if isinstance(value, str):
            agent_name = value
            model = None
        else:
            agent_name = value["agent"]
            model = value.get("model") or None
        if agent_name != "default" and agent_name not in BUILTIN_AGENTS:
            raise ValueError(f"Unknown agent: {agent_name}. Available: {list(BUILTIN_AGENTS.keys())}")
        if model:
            self._data["agent_for_phase"][phase] = {"agent": agent_name, "model": model}
        else:
            self._data["agent_for_phase"][phase] = agent_name
    self._save()
```

## Step 5: Inject model flag in AgentRunner (consistent position)

In `pipeline/runner.py`, update command building in `headless()` to add the model flag **at the end of the command** for both agents. This ensures consistent behavior regardless of agent type.

**Headless command building (around line 285-304):**
```python
cmd = [self.agent.command]

if self.agent.command == "opencode":
    # opencode: run comes first, then flags, then message
    for f in self.agent.headless_extra_flags:
        if not f.startswith("-"):
            cmd.append(f)
    for f in self.agent.headless_extra_flags:
        if f.startswith("-"):
            cmd.append(f)
    cmd.append(f"Read {instructions_path} and follow the instructions exactly.")
else:
    # claude: -p flag, then message, then extra flags
    if self.agent.headless_flag:
        cmd.append(self.agent.headless_flag)
    cmd.append(f"Read {instructions_path} and follow the instructions exactly.")
    cmd.extend(self.agent.headless_extra_flags)

# Model flag goes at the end for ALL agents (consistent position)
if self.agent.model:
    cmd.extend([self.agent.model_flag, self.agent.model])
```

**Update AgentRunner to support agent config override for model propagation:**

```python
def __init__(self, config, agent_name=None, workdir=None):
    ...
    self._agent_config_override: Optional[AgentConfig] = None

@property
def agent(self) -> AgentConfig:
    if self._agent_config_override:
        return self._agent_config_override
    if self._agent_name:
        return self._config.agents.get(self._agent_name, self._config.current_agent)
    return self._config.current_agent

def for_phase(self, phase: str) -> "AgentRunner":
    """Create a new runner configured for a specific phase."""
    agent_config = self._config.get_agent_for_phase(phase)
    runner = AgentRunner(self._config, agent_config.name, self._workdir)
    runner._agent_config_override = agent_config
    return runner
```

